#!/usr/bin/env node
// Regenerates the plugin's two pure runtime libs from @repo/maestro-core.
//
// Why this exists: successPathSteps and the managed-region helpers are needed BOTH by the
// desktop app and by the standalone hook scripts a project copies into .claude/scripts/. Those
// scripts must run under bare `node` with no node_modules, so they cannot import a workspace
// package. Rather than maintain two implementations that silently drift, core is the source and
// these are generated CJS bundles.
//
//   pnpm --filter @repo/maestro-core build:plugin-libs
//
// The generated files are committed — a project installs them by file copy, so they have to be
// present in the repo, not produced at install time.

import { build } from "esbuild";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.resolve(here, "..");
const outDir = path.resolve(pkgRoot, "../../plugins/ai-tools-manager/scripts/lib");

const BANNER = `// GENERATED by packages/maestro-core/scripts/build-plugin-libs.mjs — DO NOT EDIT.
// Source: packages/maestro-core/src/plugin-entries/%NAME%.ts
// Regenerate with: pnpm --filter @repo/maestro-core build:plugin-libs`;

const entries = [
  { name: "maestro-session", entry: "src/plugin-entries/maestro-session.ts" },
  { name: "maestro-skill-regions", entry: "src/plugin-entries/maestro-skill-regions.ts" },
];

for (const { name, entry } of entries) {
  await build({
    entryPoints: [path.join(pkgRoot, entry)],
    outfile: path.join(outDir, `${name}.cjs`),
    bundle: true,
    platform: "node",
    target: "node22",
    format: "cjs",
    // Node built-ins stay external: the bundle must not inline a shim for fs/path.
    external: ["node:fs", "node:path", "fs", "path"],
    banner: { js: BANNER.replace("%NAME%", name) },
    legalComments: "none",
  });
  process.stdout.write(`built ${path.relative(process.cwd(), path.join(outDir, `${name}.cjs`))}\n`);
}
